il !== '' && ($showVerify ?? false)) { ?><div class="BVS4rq_notice" role="region" aria-label="Email verification"><?= Icons::svg('mail-warning', 22) ?><div><p><strong>Verify your email</strong> Confirm <?= View::e($account->email) ?> with a 6-digit code.</p><button type="button" data-pf="email-send">Send code</button><form class="pf_acct_form" novalidate hidden data-pf="email-code-form"><label for="pf-email-code">Code</label><input id="pf-email-code" inputmode="numeric" autocomplete="one-time-code" maxlength="6" data-pf="email-code"/><button type="submit" class="pf_acct_btn">Verify email</button></form><p class="BVS4rq_result" role="status" data-pf="email-result" hidden></p></div></div><?php } ?><div class="P71-SG_profile"><img alt="" loading="lazy" width="150" height="150" decoding="async" data-nimg="1" class="P71-SG_profileMark" style="color:transparent" src="/assets/images/figma/lotus-emblem.svg"/><span class="P71-SG_avatar"><?= $account->avatarImg() ?><span class="P71-SG_avatarInitial" aria-hidden="true"><?php if ($account->initial !== '') { echo View::e($account->initial); } else { ?><svg xmlns="http://www.w3.org/2000/svg" width="28" height="28" viewBox="0 0 24 24" fill="currentColor" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="12" cy="8" r="5"></circle><path d="M20 21a8 8 0 0 0-16 0"></path></svg><?php } ?></span></span><div><h2><?= $account->first !== '' ? 'Hello, ' . View::e($account->first) : 'Hello' ?></h2><p>Welcome to Pratyangi Fashions</p><div class="P71-SG_profileMeta"><?php if ($memberSince !== '') { ?><span>Member since <?= View::e($memberSince) ?></span><?php } ?><?php if ($account->email !== '') { ?><span><?= View::e($account->email) ?><?php if (!$emailVerified && !($showVerify ?? false)) { ?> &middot; <a class="pf_verifyHint" href="/account?verify=1">Verify email</a><?php } ?></span><?php } ?><?php if ($mobile !== '') { ?><span><?= View::e($mobile) ?></span><?php } ?></div></